from corpus_revision_authoring import add,Q,save

add('P22-G2-S1-01','단추가 두 번 이사한 까닭',
'''민서는 단추 여섯 개를 나누어 담았어요. 처음에는 색을 보고 빨간 단추와 파란 단추를 따로 담았어요. 빨간 단추는 모양이 달라도 같은 그릇에 넣었어요. 이때는 색이 나누는 기준이었어요.
다음에는 동그란 단추와 네모난 단추를 따로 담았어요. 색이 달라도 모양이 같으면 함께 넣었어요. 단추 자체가 달라진 것은 아니에요. 살펴보는 기준이 바뀌어 단추의 자리가 달라진 거예요.
민서는 그릇 앞에 기준을 써 놓았어요. 친구가 이어서 정리할 때에도 같은 기준을 쓸 수 있게 하려는 것이었어요.''',
'''빨간 동그라미 단추는 처음에는 빨간 네모 단추와 함께 있었어요. 두 번째에는 파란 동그라미 단추와 함께 있었어요. 함께 놓인 단추의 색만 보면 두 번째 분류가 틀렸다고 생각할 수 있어요. 지금 어떤 기준을 쓰는지 먼저 확인해야 해요.''',
'''친구는 빨간 단추 한 개를 좋아해서 따로 담고 싶었어요. 하지만 색을 기준으로 나누는 중에 좋아하는 정도를 섞어 쓰면 같은 색의 단추가 흩어져요. 한 기준으로 나누는 동안에는 그 기준을 끝까지 지켜야 해요. 다른 기준을 쓰고 싶다면 새 기준을 먼저 알려 주고 다시 나누어요.''',
[Q('처음에 단추를 나눈 기준은 무엇인가요?','색이에요.',1,'색이 나누는 기준'),Q('빨간 단추와 파란 단추가 같은 그릇에 들어갈 수 있는 까닭은 무엇인가요?','두 번째에는 모양이 기준이라서 모양이 같으면 함께 넣어요.',2,'색이 달라도 모양이 같으면'),Q('파란 네모 단추는 두 번째에 어떤 단추와 함께 놓일까요?','색이 달라도 네모난 단추와 함께 놓여요.',2,'네모난 단추를 따로'),Q('자리가 바뀌었으니 단추의 모양도 바뀌었다고 해도 되나요?','단추 자체가 아니라 기준이 바뀐 것이에요.',2,'단추 자체가 달라진 것은 아니에요.')],
('블록을 색으로 나누다가 모양으로 다시 나누었어요. 빨간 삼각형 블록이 있어요.','다시 나눌 때 함께 놓을 것은 무엇인가요?',['파란 삼각형 블록','빨간 네모 블록','가장 마음에 드는 동그라미 블록'],[1,2],'바뀐 모양 기준을 적용해요.',['모양이 같아요.','이전의 색 기준을 썼어요.','새로운 다른 기준을 섞었어요.']),[('기준','나누거나 판단할 때 따르는 것')],'기준 변경·동일 기준 유지와 새 물체 분류를 추가.')

add('P22-G2-S1-02','같은 잎, 다른 묶음',
'''두 모둠이 떨어진 잎을 살폈어요. 첫째 모둠은 가장자리가 매끈한 잎과 톱니처럼 생긴 잎으로 나누었어요. 색과 크기는 이번 기준에 넣지 않았어요. 큰 잎도 가장자리가 매끈하면 매끈한 잎끼리 모았어요.
둘째 모둠은 크기로 나누었어요. 나란히 놓고 길이를 비교해 작은 잎과 큰 잎을 따로 모았어요. 가장자리 모양은 보지 않았어요. 같은 잎도 나누는 기준에 따라 다른 묶음에 들어갈 수 있어요.
두 모둠은 자기 기준을 먼저 말한 뒤 결과를 비교했어요. 놓인 자리가 다르다는 이유만으로 서로 틀렸다고 하지 않았어요.''',
'''민지는 큰 잎과 작은 잎의 사이에 있는 잎을 들었어요. 어느 쪽인지 애매했어요. 둘째 모둠은 기준이 되는 잎을 가운데 놓고 그보다 긴지 짧은지 비교하기로 했어요. 사람마다 다른 눈짐작을 줄이려는 방법이었어요.''',
'''색을 살피려는 새 모둠은 초록색과 노란색을 기준으로 삼았어요. 앞의 두 모둠과 목적이 달라져서 다른 기준을 정한 거예요. 한 가지 분류만 늘 옳은 것은 아니지만, 정한 기준에 맞게 끝까지 나누었는지는 확인할 수 있어요. 분류 결과와 분류의 기준을 함께 기록해요.''',
[Q('첫째 모둠은 잎의 무엇을 보았나요?','가장자리의 모양을 보았어요.',1,'가장자리가 매끈한 잎'),Q('같은 큰 잎이 두 모둠에서 다른 잎과 묶일 수 있는 까닭은 무엇인가요?','첫째는 가장자리, 둘째는 크기가 기준이기 때문이에요.',[1,2],'나누는 기준에 따라'),Q('가장자리가 톱니 모양인 작은 잎은 둘째 모둠에서 어디에 놓이나요?','작은 잎의 묶음에 놓여요.',2,'작은 잎과 큰 잎을 따로'),Q('두 모둠의 결과가 다르면 꼭 한 모둠이 틀린 것인가요?','서로 다른 기준을 쓰므로 결과가 다를 수 있어요.',3,'서로 틀렸다고 하지 않았어요.')],
('조약돌을 처음에는 밝은 색과 어두운 색으로, 다음에는 큰 것과 작은 것으로 나누었어요.','두 번째 분류를 확인할 때 볼 것은 무엇인가요?',['돌의 크기','돌의 색만','돌을 주운 사람 이름'],[1,2],'현재 기준에 맞는 특징을 확인해요.',['바뀐 기준이에요.','이전 기준이에요.','정하지 않은 기준이에요.']),[('가장자리','물건의 바깥쪽 끝부분'),('묶음','함께 모아 놓은 것')],'모호한 크기 기준을 비교 기준물로 보강하고 결과 차이와 오류를 구별.')

add('P22-G2-S2-01','놀이 표가 알려 주는 것',
'''여덟 명이 하고 싶은 놀이를 하나씩 골랐다고 해 보아요. 공놀이는 3명, 그림 놀이는 4명, 쌓기 놀이는 1명이 골랐어요. 이 수는 읽기 연습을 위한 가상 자료예요. 한 사람은 한 번만 세었어요.
그림 놀이를 고른 사람은 공놀이보다 1명 많아요. 세 수를 모두 더하면 8명이 되어 처음의 사람 수와 맞아요. 수를 비교할 때에는 무엇을 센 수인지와 한 사람을 몇 번 세었는지 함께 살펴요.
가장 많이 고른 것은 그림 놀이예요. 그렇다고 여덟 명 모두 그림 놀이를 원했다는 뜻은 아니에요. 공놀이나 쌓기 놀이를 고른 사람도 있어요.''',
'''민지는 그림 놀이의 이름을 크게 쓰고 나머지는 작게 썼어요. 친구는 글자 크기가 아니라 적힌 사람 수를 비교해야 한다고 했어요. 놀이를 정할 때 공간과 준비물도 필요하지만, 이 자료에는 희망한 사람 수만 들어 있어요.''',
'''다음 조사에서는 한 사람이 놀이 두 개까지 고르게 했어요. 이때 놀이별 수를 더하면 사람 수보다 커질 수 있어요. 처음 조사처럼 한 번씩 세었다고 생각하면 잘못 읽게 돼요. 두 표를 비교하기 전에는 질문과 세는 방법이 같은지 먼저 확인해야 해요.''',
[Q('그림 놀이를 고른 사람은 몇 명인가요?','4명이에요.',1,'그림 놀이는 4명'),Q('그림 놀이와 공놀이를 고른 사람 수는 얼마나 다른가요?','그림 놀이가 1명 많아요.',[1,2],'공놀이보다 1명 많아요.'),Q('세 놀이의 수를 더한 값이 8인 까닭은 무엇인가요?','여덟 명이 하나씩 고르고 한 번씩 세었기 때문이에요.',[1,2],'한 사람은 한 번만'),Q('‘모두 그림 놀이를 좋아한다’는 말은 자료와 맞나요?','다른 놀이를 고른 사람도 있으므로 모두라고 할 수 없어요.',3,'공놀이나 쌓기 놀이')],
('열 명이 하나씩 고른 결과, 달리기 6명·공놀이 4명이었어요.','알맞은 설명은 무엇인가요?',['달리기가 2명 많지만 공놀이를 고른 사람도 있어요.','열 명 모두 달리기를 원해요.','공놀이가 2명 더 많아요.'],[1,2,3],'차이를 계산하면서 전체로 넓혀 말하지 않아요.',['수와 범위를 함께 지켰어요.','많음을 모두로 바꾸었어요.','비교 방향을 뒤집었어요.']),[('가상','설명하기 위해 만들어 본 것'),('비교','나란히 살펴 같고 다른 점을 찾음')],'외부 표 없이도 수치와 단위·중복 집계 조건을 읽을 수 있게 재구성.')

add('P22-G2-S2-02','상자 하나면 충분할까요?',
'''만들기 시간에 가 상자와 나 상자를 준비했어요. 가 상자에는 가위 3개와 풀 1개, 나 상자에는 가위 1개와 풀 3개가 있어요. 이 수는 연습을 위해 만든 기록이에요. 가위는 종이를 자를 때, 풀은 붙일 때 써요.
두 친구가 가위와 풀을 각각 하나씩 쓰려고 해요. 가 상자만 가져오면 풀 하나가 부족해요. 나 상자만 가져오면 가위 하나가 부족해요. 두 상자에서 필요한 물건을 골라야 두 친구 모두 자기 도구를 쓸 수 있어요.
상자 속 물건의 전체 수만 세면 두 상자는 각각 4개로 같아요. 하지만 어떤 물건이 몇 개인지에 따라 할 수 있는 일이 달라져요.''',
'''민지는 가위 두 개와 풀 두 개를 모아 놓고 남은 것을 따로 적었어요. 필요한 수와 준비한 수를 나란히 비교했어요. 물건 수가 많다고 무조건 준비가 끝난 것은 아니에요. 필요한 종류가 빠지지 않아야 해요.''',
'''다음에는 친구 셋이 함께 도구를 돌려 쓰기로 했어요. 처음처럼 각자 하나씩 갖는 상황과 필요한 수가 달라질 수 있어요. 도구의 수를 정하기 전에는 동시에 쓰는지, 함께 쓰는지도 확인해야 해요. ‘친구 수만큼 반드시 필요하다’는 말에는 각자 쓴다는 조건이 숨어 있어요.''',
[Q('나 상자에는 풀이 몇 개 있나요?','3개예요.',1,'풀 3개'),Q('가 상자만 가져오면 두 친구에게 무엇이 부족한가요?','풀이 하나 부족해요.',[1,2],'풀 하나가 부족해요.'),Q('두 상자의 전체 물건 수가 같아도 쓰임이 다른 까닭은 무엇인가요?','물건의 종류별 수가 다르기 때문이에요.',[1,3],'어떤 물건이 몇 개인지'),Q('‘물건 네 개면 두 친구의 준비가 끝난다’고 해도 되나요?','가위와 풀이 각각 두 개 있는지도 확인해야 해요.',[1,2],'가위와 풀을 각각 하나씩')],
('친구 둘이 연필과 지우개를 각각 하나씩 써요. 연필은 3개, 지우개는 1개예요.','무엇을 더 준비해야 하나요?',['지우개 1개','연필 1개','전체가 4개이므로 더 필요 없음'],[2,3],'전체 수보다 종류별 필요 수를 맞추어요.',['부족한 종류를 찾았어요.','이미 충분한 종류를 더했어요.','종류별 조건을 빠뜨렸어요.']),[('각각','하나하나 따로'),('부족','필요한 만큼에 못 미침')],'표의 수와 도구 쓰임, 동시 사용 조건을 연결.')

add('G2-EXP-V1-1','마을 지도의 장소를 골라요',
'''우리 마을에는 함께 쓰는 장소가 있어요. 마을 안내에는 우체국에서 편지와 소포를 보낼 수 있다고 적혀 있어요. 도서관에서는 책을 읽고 빌릴 수 있다고 안내해요. 보건소 안내에는 건강에 관한 상담을 받을 수 있다고 나와요.
민지는 먼 곳의 할머니께 편지를 보내려 해요. 책을 읽는 곳이 가까워도 지금 할 일과 맞는 곳을 골라야 해요. 민지는 편지를 보내는 일을 우체국의 설명과 연결했어요.
같은 마을의 장소라도 하는 일이 모두 같지는 않아요. 안내에서 필요한 일을 찾고, 그 장소의 이용 시간도 확인하면 좋아요.''',
'''친구는 가장 가까운 장소만 지도에 동그라미를 했어요. 민지는 가까운지도 도움이 되는 정보지만, 그곳에서 원하는 일을 할 수 있는지가 먼저라고 했어요. 두 장소가 모두 편리해 보여도 이번 목적에 맞는 곳을 골라야 해요.''',
'''안내에는 특별한 행사 때문에 도서관의 책 빌리는 시간이 바뀐다고 쓰여 있었어요. 예전에 빌린 적이 있어도 오늘 같은 시간에 할 수 있다고 단정할 수는 없어요. 장소의 평소 역할과 지금 이용할 수 있는 조건을 함께 읽으면 헛걸음을 줄일 수 있어요.''',
[Q('편지를 보내는 곳은 어디인가요?','우체국이에요.',1,'우체국에서 편지와 소포'),Q('도서관이 가까워도 우체국을 골라야 하는 까닭은 무엇인가요?','지금 목적이 책 읽기가 아니라 편지 보내기이기 때문이에요.',[1,2],'편지를 보내는 일을 우체국'),Q('책을 빌리려는 친구는 어느 안내를 더 읽어야 하나요?','도서관 안내와 이용 시간을 읽어요.',[1,3],'그 장소의 이용 시간'),Q('‘함께 쓰는 곳이므로 어디서나 같은 일을 할 수 있다’는 말은 맞나요?','장소마다 하는 일이 달라서 맞지 않아요.',3,'하는 일이 모두 같지는 않아요.')],
('학교 안내에 음악실은 악기 연습, 미술실은 그림 그리기를 하는 곳이라고 쓰여 있어요. 붓으로 그림을 그리려 해요.','목적에 맞는 장소는 무엇인가요?',['미술실','더 가까운 음악실만','안내를 보지 않고 고른 아무 방'],[2,3],'가까움만 보지 않고 목적과 역할을 연결해요.',['원하는 활동과 맞아요.','장소의 역할을 빠뜨렸어요.','필요한 조건을 확인하지 않았어요.']),[('공공장소','여러 사람이 함께 이용하는 곳'),('이용','필요한 일에 씀')],'의료기관의 모든 치료 가능성 단정을 피하고 역할·이용 조건 판단으로 개정.')

add('G2-EXP-V1-2','채소를 나누는 새로운 기준',
'''채소를 나눌 때에는 먹는 부분을 기준으로 삼을 수 있어요. 당근과 무는 주로 뿌리 부분을 먹어요. 시금치와 배추는 주로 잎 부분을 먹어요. 오이와 토마토는 열매 부분을 먹어요. 여기서는 채소의 색을 기준으로 나눈 것이 아니에요.
민지는 초록색이라는 이유로 오이와 시금치를 한 칸에 넣었어요. 하지만 먹는 부분을 기준으로 한 표에서는 서로 다른 칸에 들어가요. 같은 색이어도 먹는 부분이 다를 수 있기 때문이에요.
기준을 바꾸어 색으로 다시 나누는 것은 가능해요. 다만 먹는 부분으로 나누다가 중간에 색을 섞어 쓰면 분류가 뒤섞여요.''',
'''민지는 표 위에 ‘먹는 부분’이라고 제목을 썼어요. 친구는 제목을 보고 토마토를 열매 칸에 놓았어요. 빨간색 칸은 이 표에 없어요. 표의 제목은 무엇을 보고 나누었는지 알려 주는 중요한 단서예요.''',
'''음식 가게에서는 보관할 곳에 따라 채소를 나눌 수도 있어요. 식물의 부분을 알아보는 수업과 보관하려는 일은 목적이 달라요. 그래서 분류 결과가 다를 수 있어요. 어느 표가 무조건 틀렸다고 말하기 전에 목적과 기준을 먼저 읽어야 해요.''',
[Q('당근과 무는 주로 어느 부분을 먹나요?','뿌리 부분을 먹어요.',1,'당근과 무는 주로 뿌리'),Q('오이와 시금치가 다른 칸에 들어가는 까닭은 무엇인가요?','이 표는 색이 아니라 먹는 부분이 기준이기 때문이에요.',[1,2],'먹는 부분을 기준으로'),Q('먹는 부분 표에서 배추와 같은 칸에 들어갈 채소는 무엇인가요?','잎을 먹는 시금치예요.',1,'시금치와 배추는 주로 잎'),Q('색이 같다는 이유만으로 같은 칸에 넣어도 되나요?','현재 기준은 먹는 부분이므로 색만으로 넣으면 안 돼요.',[2,3],'중간에 색을 섞어 쓰면')],
('동물 카드를 사는 곳으로 나누어요. 물에서 사는 카드와 땅에서 사는 카드가 있어요.','기준을 지킨 행동은 무엇인가요?',['색이 같아도 사는 곳이 다르면 따로 놓아요.','같은 색이면 모두 한 칸에 놓아요.','좋아하는 카드만 기준 없이 옮겨요.'],[2,3],'정한 기준을 끝까지 유지해요.',['현재 기준에 맞아요.','다른 기준을 섞었어요.','기준과 개인 취향을 섞었어요.']),[('뿌리','식물이 땅에 붙어 물 등을 빨아들이는 부분'),('분류','기준에 따라 나눔')],'식물 전체를 단순 범주화하지 않고 주로 먹는 부분이라는 기준을 명시.')

add('G2-EXP-V1-3','강낭콩 기록의 빈칸',
'''민지는 강낭콩 씨앗을 심고 변화를 기록했어요. 처음 기록에는 씨앗에서 뿌리가 나온 모습이 있어요. 다음 기록에는 떡잎이 땅 위로 나온 모습이 있어요. 그 뒤에는 본잎이 자란 모습을 그렸어요. 이는 민지가 관찰한 자람의 차례예요.
민지는 매일 같은 시각에 보려고 했지만 하루는 보지 못했어요. 그날의 칸은 빈칸으로 두었어요. 보지 못했다는 것은 그날 아무 변화도 없었다는 뜻이 아니에요.
친구와 기록을 비교하니 본잎을 본 날짜가 달랐어요. 씨앗을 심은 날이나 기르는 조건이 다를 수 있으므로 날짜만으로 누가 잘못했다고 하지는 않았어요.''',
'''기록에는 날짜와 함께 흙의 모습도 짧게 적었어요. 민지는 ‘갑자기 자랐다’라고만 쓰기보다 전날과 오늘 본 부분을 나란히 보았어요. 차례를 적을 때에는 처음부터 보았던 것처럼 빈칸을 마음대로 채우지 않았어요.''',
'''한 친구는 본잎 사진 한 장만으로 뿌리가 나온 정확한 날을 알 수 있다고 했어요. 민지는 사진이 찍힌 때의 모습은 알지만 앞선 날짜는 기록을 더 찾아야 한다고 했어요. 자라는 차례를 안다는 것과 어떤 날 일어났는지 안다는 것은 서로 다른 정보예요.''',
[Q('떡잎이 나온 모습 뒤에 기록한 것은 무엇인가요?','본잎이 자란 모습이에요.',1,'그 뒤에는 본잎이'),Q('빈칸을 변화 없음으로 읽으면 안 되는 까닭은 무엇인가요?','그날 관찰하지 않았기 때문에 변화가 없었는지는 몰라요.',2,'아무 변화도 없었다는 뜻이 아니에요.'),Q('심은 날이 다른 두 기록을 비교할 때 무엇을 먼저 맞추어야 하나요?','심은 뒤 며칠이 지났는지 같은 기준으로 비교해야 해요.',3,'씨앗을 심은 날'),Q('‘같은 날 본잎이 안 나왔으니 한 기록은 틀렸다’는 말이 타당한가요?','심은 날이나 기르는 조건이 다를 수 있어 단정할 수 없어요.',3,'기르는 조건이 다를 수')],
('월요일에 찍은 새싹 사진과 금요일에 찍은 잎 사진만 있어요. 수요일에는 보지 못했어요.','수요일 기록을 어떻게 해야 하나요?',['관찰하지 못했다고 남겨요.','변화가 전혀 없었다고 써요.','본잎이 정확히 수요일에 나왔다고 써요.'],[2],'기록이 없는 것과 변화가 없는 것을 구별해요.',['확인한 범위를 지켰어요.','미관찰을 무변화로 바꾸었어요.','정확한 날짜를 꾸며 냈어요.']),[('떡잎','씨앗에서 먼저 나오는 잎'),('본잎','떡잎 뒤에 자라는 잎')],'고정 개화 색·계절 단정을 지우고 관찰 공백과 비교 조건을 보강.')

add('G2-EXP-V1-4','한옥의 다른 두 공간',
'''한옥을 소개한 글에는 마루와 온돌방이 나와요. 마루는 나무로 바닥을 만든 공간이에요. 문을 열어 바람이 통하도록 이용할 수 있어요. 온돌방은 바닥을 데워 실내를 따뜻하게 하는 구조를 이용해요.
여름에 바람을 쐬려는 일과 추운 날 따뜻하게 지내려는 일은 달라요. 사람들은 날씨와 하려는 일에 맞게 공간을 이용했어요. 마루와 온돌방은 같은 집 안에서도 서로 다른 도움을 줄 수 있어요.
집의 구조만 있다고 늘 시원하거나 따뜻한 것은 아니에요. 바람이 부는지, 문이 열려 있는지, 방을 데웠는지도 함께 보아야 해요.''',
'''민지는 마루 그림에 바람이 지나가는 화살표를 그렸어요. 온돌방 그림에는 데워지는 바닥에 표시했어요. 두 곳을 모두 ‘좋은 곳’이라고만 쓰면 어떤 도움을 주는지 구별하기 어려워요. 구조와 쓰임을 이어 설명해야 해요.''',
'''친구는 더운 날에도 문을 모두 닫은 마루가 언제나 시원할 거라고 말했어요. 민지는 바람이 통할 조건이 있는지 확인하자고 했어요. 공간 이름만으로 결과를 정하면 실제 조건을 빠뜨릴 수 있어요. 옛집을 이해할 때도 하나의 특징으로 모든 집을 똑같이 설명하지 않아요.''',
[Q('바닥을 데우는 구조를 이용하는 곳은 어디인가요?','온돌방이에요.',1,'바닥을 데워'),Q('마루와 온돌방을 서로 다르게 이용한 까닭은 무엇인가요?','날씨와 하려는 일에 필요한 도움이 달랐기 때문이에요.',[1,2],'날씨와 하려는 일'),Q('마루에서 바람이 통할지 알려면 무엇을 더 살펴야 하나요?','바람과 문이 열려 있는지 등을 살펴요.',3,'문이 열려 있는지'),Q('‘한옥이면 어떤 날에도 저절로 시원하고 따뜻하다’는 말은 타당한가요?','이용 조건도 필요하므로 구조만으로 단정할 수 없어요.',3,'늘 시원하거나 따뜻한 것은 아니에요.')],
('새 쉼터에는 그늘막과 바람막이가 있어요. 햇빛을 피하려는 날이에요.','목적과 구조를 알맞게 이은 것은 무엇인가요?',['그늘막으로 햇빛 가리기','바람막이만 있으면 모든 날 시원하다고 하기','구조를 보지 않고 이름만 고르기'],[1,2,3],'필요한 도움과 실제 구조를 연결해요.',['목적에 맞는 기능이에요.','다른 조건을 무시했어요.','판단할 근거를 보지 않았어요.']),[('온돌','바닥을 데워 방을 따뜻하게 하는 방식'),('구조','부분들이 이루어진 모습')],'과장된 기후 적응 설명을 조건부 기능 설명으로 수정.')

add('G2-EXP-V2-1','땅속에 있다고 모두 뿌리일까요?',
'''당근과 감자는 모두 땅속에서 자란 부분을 먹어요. 하지만 식물의 같은 부분은 아니에요. 당근은 뿌리가 굵어진 것이고, 감자는 줄기의 일부가 굵어진 것이에요. 감자에는 새싹이 나올 수 있는 ‘눈’이 있어요.
양파의 둥근 부분에는 두꺼워진 잎이 여러 겹 모여 있어요. 아래쪽에는 짧은 줄기도 있어요. 그래서 양파의 하얀 겹을 모두 굵은 줄기라고 설명하면 정확하지 않아요.
식물의 부분을 알아볼 때에는 땅 위인지 아래인지만 보지 않아요. 싹이 나오는 자리나 겹쳐진 모습 같은 특징을 함께 살펴요.''',
'''민지는 감자를 뿌리라고 적었다가 설명을 읽고 고쳤어요. 처음 생각한 까닭은 땅속에 있었기 때문이에요. 하지만 같은 장소에 있다는 사실만으로 같은 부분이라고 정할 수는 없었어요. 새로운 단서를 만나면 분류를 바꿀 수 있어요.''',
'''친구가 낯선 식물 사진 한 장을 보여 주었어요. 흙 아래의 둥근 부분만 보였어요. 민지는 사진만으로 뿌리인지 줄기인지 확정하지 않았어요. 다른 특징을 더 보여 주는 자료를 찾기로 했어요. 모양이 비슷한 것과 같은 식물 부분인 것은 다를 수 있어요.''',
[Q('감자는 식물의 어느 부분이 굵어진 것인가요?','줄기의 일부예요.',1,'줄기의 일부가 굵어진'),Q('당근과 감자를 같은 부분이라고 할 수 없는 까닭은 무엇인가요?','둘 다 땅속에 있지만 당근은 뿌리, 감자는 줄기이기 때문이에요.',1,'당근은 뿌리가'),Q('땅속의 둥근 부분 사진만 있다면 무엇을 더 살피면 좋나요?','싹의 자리나 겹쳐진 모습 같은 특징을 더 살펴요.',3,'싹이 나오는 자리'),Q('양파의 하얀 겹은 모두 줄기라는 말이 맞나요?','두꺼워진 잎이 여러 겹 모인 것이므로 맞지 않아요.',2,'두꺼워진 잎이 여러 겹')],
('두 물건이 물에 떠 있어요. 하나는 나무, 다른 하나는 플라스틱이에요.','글에서 배운 판단 방법과 맞는 말은 무엇인가요?',['같은 곳에 뜬다고 재료까지 같지는 않아요.','물에 뜨면 모두 나무예요.','재료가 다르면 같은 곳에 있을 수 없어요.'],[1,3],'한 공통 특징으로 전체 성질을 같다고 하지 않아요.',['공통점과 다른 점을 구별했어요.','한 특징으로 재료를 단정했어요.','다른 성질이 공통점을 없애지는 않아요.']),[('눈','감자에서 새싹이 나올 수 있는 자리'),('겹','포개어진 한 층')],'양파의 먹는 겹을 전부 줄기로 설명한 오류 수정. 장소와 식물 기관을 구별.')

add('G2-EXP-V2-2','헌 종이를 다시 쓸 때',
'''헌 종이를 모아 다시 종이를 만들 수 있어요. 수업에서는 선생님이 준비한 종이죽을 망으로 건져 보았어요. 물에 풀어진 종이 조각을 평평하게 펴고 물기를 뺀 뒤 충분히 말렸어요. 젖어 있을 때와 말랐을 때의 모습은 달랐어요.
민지는 물기가 남은 종이에 글씨를 쓰려다가 찢었어요. 모양이 종이처럼 보인다고 바로 쓸 수 있는 것은 아니에요. 충분히 말랐는지도 확인해야 해요.
헌 종이를 다시 쓰면 새 재료를 쓰는 양을 줄이는 데 도움이 될 수 있어요. 하지만 만드는 데 물과 일이 필요해요. 다시 만든다고 어떤 자원도 들지 않는 것은 아니에요.''',
'''친구들은 종이죽을 두께가 비슷하도록 폈어요. 한쪽에 많이 몰리면 마르는 모습도 고르지 않을 수 있었어요. 만든 과정과 결과를 함께 적으면 다음에 무엇을 고쳐 볼지 생각하기 좋아요.''',
'''두 모둠의 종이 중 하나가 더 늦게 말랐어요. 민지는 그것이 종이 조각의 종류 때문이라고 바로 말하지 않았어요. 두께와 놓아둔 곳도 달랐기 때문이에요. 서로 다른 결과의 까닭을 찾으려면 함께 달라진 조건이 무엇인지 살펴야 해요.''',
[Q('망으로 건진 종이죽에서 물기를 뺀 뒤 한 일은 무엇인가요?','충분히 말렸어요.',1,'물기를 뺀 뒤 충분히 말렸어요.'),Q('민지의 종이가 찢어진 까닭은 무엇인가요?','물기가 남아 있었는데 쓰려고 했기 때문이에요.',2,'물기가 남은 종이'),Q('모양이 완성된 것 같아도 쓰기 전에 확인할 것은 무엇인가요?','충분히 말랐는지 확인해요.',2,'충분히 말랐는지도'),Q('‘재생종이는 아무 자원도 쓰지 않는다’는 말은 맞나요?','물과 일이 필요하므로 맞지 않아요.',3,'만드는 데 물과 일이 필요해요.')],
('물감으로 만든 이름표를 붙이려 해요. 모양은 완성됐지만 물감이 아직 젖어 있어요.','알맞은 판단은 무엇인가요?',['붙이기 전에 충분히 말랐는지 확인해요.','모양만 완성되면 바로 붙여요.','젖었어도 만든 순서는 중요하지 않아요.'],[1,2],'다음 일을 할 준비가 된 상태인지 살펴요.',['상태 조건을 적용했어요.','겉모양만으로 판단했어요.','필요한 과정과 상태를 빠뜨렸어요.']),[('재생','썼던 것을 다시 쓸 수 있게 만듦'),('자원','무언가를 만드는 데 쓰는 재료 등')],'어린이에게 믹서 사용을 직접 지시하던 설명과 자원 무사용 과장을 고침.')

add('G2-EXP-V2-3','개미집 모형의 길을 읽어요',
'''교실의 개미집 모형에는 방 세 개와 통로가 있어요. 입구에서 첫 통로를 따라가면 먹이를 놓는 방이 나와요. 그 방 옆 통로를 지나면 애벌레를 돌보는 방이 있어요. 설명을 위해 단순하게 만든 모형이에요.
민지는 입구에서 바로 애벌레 방으로 선을 그었어요. 친구는 모형에 그런 통로가 없다고 했어요. 민지는 실제로 이어진 통로를 따라 선을 다시 그었어요. 가까워 보이는 방이 언제나 바로 이어지는 것은 아니에요.
개미집은 종류와 환경에 따라 모습이 달라요. 이 모형의 방 이름과 위치가 모든 개미집에 꼭 똑같이 있다는 뜻은 아니에요.''',
'''친구들은 방을 뜻하는 동그라미와 통로를 뜻하는 선을 서로 다르게 그렸어요. 방의 위치만 보고 길을 정하는 실수를 줄이려는 거예요. 길을 설명할 때에는 시작하는 곳과 거쳐 가는 곳도 순서대로 말해야 해요.''',
'''새 모형에서는 두 방 사이에 통로 하나를 더 만들었어요. 민지는 예전 길만 고집하지 않고 달라진 연결을 살폈어요. 방의 이름이 같아도 이어지는 길이 바뀌면 갈 수 있는 차례도 달라질 수 있어요. 모형을 바꾸었을 때는 무엇이 그대로이고 무엇이 달라졌는지 나누어 확인해요.''',
[Q('입구에서 첫 통로를 따라가면 나오는 방은 무엇인가요?','먹이를 놓는 방이에요.',1,'먹이를 놓는 방이 나와요.'),Q('민지가 처음 그은 선을 고친 까닭은 무엇인가요?','모형에 실제로 이어진 통로가 아니었기 때문이에요.',2,'그런 통로가 없다고'),Q('입구에서 애벌레 방으로 가려면 어느 방을 거치나요?','먹이를 놓는 방을 거쳐요.',1,'그 방 옆 통로를 지나면'),Q('모든 개미집이 이 모형과 똑같다고 할 수 있나요?','종류와 환경에 따라 다르므로 그럴 수 없어요.',3,'종류와 환경에 따라')],
('교실 모형에서 입구는 책상 자리와, 책상 자리는 창가와 이어져 있어요. 입구와 창가는 직접 이어져 있지 않아요.','창가로 가는 길은 무엇인가요?',['입구 → 책상 자리 → 창가','입구에서 바로 창가','가까워 보이는 곳으로 아무 선 긋기'],[1,2],'가까움과 실제 연결을 구별해요.',['이어진 길을 따랐어요.','없는 연결을 만들었어요.','거리만 보고 통로를 무시했어요.']),[('모형','알아보기 쉽게 작게 본떠 만든 것'),('통로','오갈 수 있도록 이어진 길')],'모든 개미집의 고정 방·항상 청결 단정을 모형의 제한으로 전환.')

add('G2-EXP-V2-4','자전거 안내의 두 때',
'''민지는 보호자와 자전거를 타기 전에 안내를 읽었어요. 안내에는 먼저 안전모가 알맞게 씌워졌는지, 브레이크가 작동하는지 확인하라고 되어 있어요. 이는 출발 전에 살필 일이에요.
타는 동안에는 앞과 주변을 살피고, 사람이 나타나면 속도를 줄여야 해요. 안전모를 썼다고 주변을 살피는 일을 빼는 것은 아니에요. 출발 전의 준비와 타는 동안의 행동이 모두 필요해요.
안내에는 어두울 때 잘 보이도록 하는 등과 반사판도 나와요. 등은 빛을 내고 반사판은 들어온 빛을 되돌려 보여요. 반사판은 스스로 불을 켜는 물건과 달라요.''',
'''민지는 안내를 읽으며 ‘타기 전’과 ‘타는 동안’에 다른 표시를 했어요. 물건 이름만 동그라미 치면 언제 무엇을 해야 하는지 놓칠 수 있어요. 행동하는 때를 함께 표시하면 안내를 따라가기 쉬워요.''',
'''친구는 안전모와 등이 있으니 어떤 길에서도 마음껏 빨리 타도 된다고 말했어요. 민지는 장비가 모든 위험을 없애지는 않는다고 했어요. 타도 되는 장소인지, 주변에 사람이 있는지 같은 조건도 살펴야 해요. 안전 장비와 행동 규칙은 서로 대신하는 것이 아니라 함께 필요한 것이에요.''',
[Q('브레이크가 작동하는지는 언제 확인하나요?','출발 전에 확인해요.',1,'출발 전에 살필 일'),Q('안전모를 써도 주변을 살펴야 하는 까닭은 무엇인가요?','준비와 타는 동안의 행동은 모두 필요하기 때문이에요.',2,'모두 필요해요.'),Q('사람이 앞에 나타났다면 안내에 따라 무엇을 해야 하나요?','속도를 줄이며 주변을 살펴요.',2,'사람이 나타나면 속도를 줄여야'),Q('반사판에 불을 켠다고 쓴 안내는 무엇을 고쳐야 하나요?','반사판은 스스로 빛을 내는 등이 아니라 빛을 되돌려 보여 준다고 고쳐요.',3,'스스로 불을 켜는 물건과 달라요.')],
('체육 안내에 ‘시작 전 신발 끈 확인, 운동 중 앞사람과 거리 두기’가 있어요.','알맞은 행동은 무엇인가요?',['끈을 확인하고 운동 중 거리도 살펴요.','끈을 묶었으니 거리 확인은 빼요.','거리만 두고 신발은 확인하지 않아요.'],[1,2],'서로 다른 때의 조건을 함께 지켜요.',['두 때의 행동을 구별했어요.','준비로 모든 행동을 대신했어요.','시작 전 조건을 빠뜨렸어요.']),[('반사판','들어온 빛을 되돌려 잘 보이게 하는 판'),('작동','도구가 움직이거나 제 일을 함')],'반사판을 켠다는 오류와 장비만으로 안전 보장하는 읽기를 수정.')

add('G2-EXP-V3-1','같은 종이에서 다른 모양이',
'''정사각형 종이의 마주 보는 꼭짓점을 맞대어 반으로 접으면 삼각형 모양이 돼요. 마주 보는 변을 맞대어 반으로 접으면 직사각형 모양이 돼요. 출발한 종이는 같아도 맞대는 부분이 달라요.
민지는 친구가 접은 삼각형을 보았어요. 변끼리 맞대었다는 설명을 읽고 이상하다고 생각했어요. 접은 결과와 과정의 설명이 서로 맞는지 살펴야 했어요.
삼각형의 둘레에는 곧은 변이 세 개, 직사각형에는 네 개가 있어요. 민지는 그림의 방향을 돌려도 변의 수가 바뀌지 않는다는 것을 확인했어요.''',
'''친구는 종이를 비스듬히 놓자 삼각형이 다른 모양이 되었다고 말했어요. 민지는 종이를 다시 접은 것이 아니라 돌려 놓았을 뿐이라고 했어요. 보는 방향과 도형의 특징을 구별하면 이름을 바르게 붙일 수 있어요.''',
'''새 안내 그림에는 접는 선만 있고 무엇을 맞대는지 쓰여 있지 않았어요. 민지는 꼭짓점인지 변인지 덧붙이자고 했어요. 결과 그림만 보여 주는 안내와 만드는 과정을 알려 주는 안내에는 필요한 정보가 달라요. 따라 할 수 있는 설명인지 확인해 보아요.''',
[Q('꼭짓점끼리 맞대어 반으로 접으면 어떤 모양이 되나요?','삼각형 모양이에요.',1,'삼각형 모양이 돼요.'),Q('같은 종이인데 다른 모양이 된 까닭은 무엇인가요?','맞대어 접는 부분이 다르기 때문이에요.',1,'맞대는 부분이 달라요.'),Q('그림이 돌아가 있어도 삼각형인지 확인하려면 무엇을 세나요?','둘레의 곧은 변 세 개를 세어요.',3,'곧은 변이 세 개'),Q('삼각형 그림에 ‘변끼리 맞대어 접었다’고 쓰면 맞나요?','본문의 접는 과정과 결과가 맞지 않아요.',[1,2],'결과와 과정의 설명')],
('정사각형 종이를 변끼리 맞대어 반으로 접었어요. 그림을 옆으로 돌려 놓았어요.','맞는 설명은 무엇인가요?',['직사각형이며 돌려도 변은 네 개예요.','돌렸으므로 삼각형이 돼요.','원래 종이가 같으니 모든 접기 결과도 같아요.'],[1,3],'접기와 방향 돌리기를 구별해요.',['과정과 변 수를 함께 적용했어요.','방향 변화와 도형 변화를 섞었어요.','접는 조건 차이를 지웠어요.']),[('꼭짓점','변과 변이 만나는 점'),('변','도형 둘레의 곧은 선')],'그림 없는 문항의 의존성을 없애고 과정-결과 및 방향 불변성 판단 추가.')

add('G2-EXP-V3-2','올챙이 일기는 어떻게 읽을까요?',
'''민지는 올챙이가 자라는 사진을 날짜대로 모았어요. 첫 사진에는 꼬리가 있고 다리는 보이지 않았어요. 뒤의 사진에는 뒷다리가 보였고, 다음 사진에는 앞다리도 보였어요. 더 자란 사진에서는 꼬리가 짧아졌어요.
이 기록에서는 뒷다리가 보인 뒤 앞다리가 보였어요. 사진의 차례를 바꾸면 자라는 과정을 다르게 읽게 돼요. 크기가 큰 사진이라고 반드시 나중에 찍은 것은 아니므로 날짜도 확인해요.
어떤 날의 사진이 빠졌다면 그 사이의 정확한 모습을 모를 수 있어요. 뒤 사진을 보고 변화가 있었다고 생각할 수는 있지만, 보지 않은 날의 모양을 직접 관찰했다고 쓰지는 않아요.''',
'''친구는 꼬리가 짧아진 것을 보고 처음부터 꼬리가 없었다고 썼어요. 민지는 첫 사진의 긴 꼬리에 표시했어요. 지금 모습과 예전 모습을 나란히 놓으면 무엇이 달라졌는지 알 수 있어요.''',
'''다른 모둠의 올챙이는 앞다리가 보인 날짜가 달랐어요. 두 모둠의 기록을 비교하려면 관찰을 시작한 때와 기르는 조건도 확인해야 해요. 변화의 차례가 비슷하다고 모든 날짜까지 같아야 하는 것은 아니에요. 날짜와 변화의 순서를 나누어 읽어요.''',
[Q('기록에서 앞다리보다 먼저 보인 것은 무엇인가요?','뒷다리예요.',1,'뒷다리가 보였고'),Q('사진 크기만으로 차례를 정하면 안 되는 까닭은 무엇인가요?','크게 인쇄한 사진일 수도 있으므로 날짜가 필요해요.',2,'날짜도 확인해요.'),Q('꼬리가 짧아졌다는 것을 확인하려면 어떤 사진을 비교해야 하나요?','앞선 긴 꼬리 사진과 뒤의 짧은 꼬리 사진을 비교해요.',[1,3],'꼬리가 짧아졌어요.'),Q('사진이 없는 날의 모습을 보았다고 적어도 되나요?','정확히 관찰하지 않았으므로 그렇게 적으면 안 돼요.',3,'직접 관찰했다고 쓰지는 않아요.')],
('월요일에는 봉오리, 목요일에는 핀 꽃 사진이 있어요. 화요일 사진은 없어요.','자료로 할 수 있는 말은 무엇인가요?',['월요일과 목요일 사이에 꽃이 피었어요.','정확히 화요일 아침에 꽃이 피었어요.','사진이 없던 날에는 변화가 없었어요.'],[2,3],'확인한 기간과 정확히 모르는 시각을 구별해요.',['두 사진의 범위 안에서 판단했어요.','정확한 날을 근거 없이 보탰어요.','미관찰을 무변화로 바꾸었어요.']),[('봉오리','아직 활짝 피지 않은 꽃'),('과정','변해 가거나 일이 이루어지는 차례')],'관찰 기록에 집중하고 허파만으로 호흡한다는 과도한 생물 설명 삭제.')

add('G2-EXP-V3-3','집 모양과 환경을 함께 읽어요',
'''집은 사는 곳의 환경과 쓸 수 있는 재료에 따라 여러 모습으로 지어져요. 북극의 일부 지역에서는 단단한 눈 덩어리로 둥근 집을 지어 추위와 바람을 피했어요. 이런 눈집을 이글루라고 부르기도 해요. 얼음판으로만 만든 집이라는 뜻은 아니에요.
비가 많이 오는 어떤 지역에는 바닥을 땅보다 높인 집이 있어요. 물이 올라오거나 땅이 젖는 상황에 대응하는 데 도움이 될 수 있어요. 집의 구조와 주변 조건을 함께 살펴야 하는 까닭이에요.
같은 지역의 모든 사람이 같은 집에서 사는 것은 아니에요. 두 사례만으로 나라나 지역 전체의 집을 하나로 정하면 실제의 다양한 모습을 놓칠 수 있어요.''',
'''민지는 집의 모양만 그린 카드에 주변 환경 설명을 붙였어요. 높은 기둥이 있다는 말과 왜 바닥을 높였는지는 다른 정보예요. 두 자료를 이어 읽으면 구조가 어떤 필요와 연결되는지 생각할 수 있어요.''',
'''친구는 기둥이 높은 집 사진만 보고 어느 나라의 집인지 정했어요. 하지만 비슷한 필요가 있는 여러 곳에서 비슷한 모양을 쓸 수 있어요. 나라 이름을 알려면 사진이 찍힌 장소 같은 다른 자료가 필요해요. 모양의 이유를 짐작하는 것과 정확한 장소를 아는 것은 구별해요.''',
[Q('글에 나온 눈집은 주로 무엇을 쌓아 만들었나요?','단단한 눈 덩어리예요.',1,'단단한 눈 덩어리'),Q('어떤 지역에서 바닥을 높인 까닭은 무엇인가요?','물이 올라오거나 땅이 젖는 상황에 대응하려는 거예요.',2,'물이 올라오거나 땅이 젖는'),Q('집의 구조가 필요한 이유를 생각하려면 모양과 무엇을 함께 읽나요?','주변 환경과 조건을 함께 읽어요.',[1,2],'주변 조건을 함께'),Q('‘북극 사람은 모두 눈집에 산다’는 말은 타당한가요?','일부 사례이므로 모든 사람에게 넓히면 안 돼요.',3,'모든 사람이 같은 집')],
('비가 자주 오는 곳의 창고에 물건을 바닥보다 높게 놓는 선반이 있어요.','구조와 필요를 연결한 말은 무엇인가요?',['물건이 젖는 상황에 대비한 것일 수 있어요.','높은 선반만 보면 나라 이름을 알 수 있어요.','모든 창고는 반드시 같은 선반을 써요.'],[2,3],'구조의 가능한 기능과 단정할 수 없는 정보를 나누어요.',['제시된 환경과 연결했어요.','형태에서 장소를 단정했어요.','한 사례를 전체로 넓혔어요.']),[('환경','주변의 날씨나 땅 같은 조건'),('대응','상황에 맞게 대처함')],'이글루의 재료 오류와 북극·열대 주거의 획일적 일반화 수정.', ['https://publications.gc.ca/collections/collection_2017/aanc-inac/R32-75-1986-eng.pdf'])

add('G2-EXP-W1','자로 재는 방법을 설명해요',
'''민지는 동생에게 센티미터 자를 쓰는 방법을 알려 주려고 해요. 이 자에는 끝부분보다 조금 안쪽에 0 눈금이 있어요. 민지는 물건의 한쪽 끝을 자의 0 눈금에 맞추고, 다른 쪽 끝에 닿는 눈금을 읽었어요.
동생은 자의 맨 끝을 물건 끝에 맞추었어요. 그러자 같은 물건도 읽은 수가 달라졌어요. 물건이 갑자기 길어진 것이 아니라 재기 시작한 자리가 달라진 거예요.
민지는 ‘바르게 재라’고만 하지 않았어요. 0 눈금에 맞춘 그림과 자의 맨 끝에 맞춘 그림을 나란히 보여 주며 어느 자리를 봐야 하는지 설명했어요.''',
'''설명에는 ‘물건을 자와 나란히 놓기’도 더했어요. 자가 비스듬하면 같은 부분을 곧게 재기 어려워요. 처음 재는 동생에게는 규칙의 이름보다 손으로 어디를 맞추는지 보여 주는 것이 도움이 되었어요.''',
'''새 자는 0 눈금이 지워져 있었어요. 동생은 다른 눈금에서 재기 시작해도 끝의 수만 읽으면 된다고 했어요. 민지는 시작한 수를 빼야 한다는 다른 계산이 필요하므로, 지금은 0이 보이는 자로 방법을 익히자고 했어요. 처음 배운 규칙에는 0에서 시작한다는 조건이 있어요.''',
[Q('물건의 한쪽 끝은 어디에 맞추나요?','자의 0 눈금에 맞추어요.',1,'자의 0 눈금에 맞추고'),Q('같은 물건인데 읽은 수가 달라진 까닭은 무엇인가요?','재기 시작한 자리가 달랐기 때문이에요.',2,'재기 시작한 자리가 달라진'),Q('동생이 잘못 맞춘 곳을 알려 주려면 어떤 두 곳을 비교하나요?','자의 맨 끝과 0 눈금을 비교해요.',[1,3],'0 눈금에 맞춘 그림'),Q('‘바르게 재라’는 말만으로 처음 재는 사람이 따라 하기 충분한가요?','어느 자리를 맞추는지 구체적인 설명이 더 필요해요.',3,'어느 자리를 봐야 하는지')],
('새 친구에게 색종이를 반으로 접는 방법을 알려 주어요. 친구는 어떤 모서리를 맞출지 몰라요.','도움이 되는 설명은 무엇인가요?',['맞댈 두 모서리를 표시해서 보여 줘요.','정확하게 하라는 말만 반복해요.','완성한 종이만 숨겨 두어요.'],[3],'독자가 모르는 구체적인 행동을 알려 주어요.',['막힌 위치를 직접 설명해요.','필요한 정보를 주지 않았어요.','따라 할 자료가 없어요.']),[('눈금','길이나 양을 읽도록 표시한 선'),('독자','글을 읽는 사람')],'글쓰기 계획 용어 암기 대신 실제 오측정과 독자에게 필요한 정보 판단.')

add('G2-EXP-W2','갈고리와 고리가 만날 때',
'''찍찍이 테이프에는 서로 다른 두 면이 있어요. 한쪽에는 작은 갈고리들이, 다른 쪽에는 작은 고리들이 있어요. 두 면을 붙이면 갈고리가 고리에 걸려 쉽게 떨어지지 않아요. 접착제가 마르는 방식과는 달라요.
옷이나 털에 달라붙는 식물의 열매를 관찰한 일이 이런 도구를 만드는 생각으로 이어졌어요. 중요한 것은 식물의 색을 그대로 따라 한 것이 아니라 걸리는 모양을 살핀 것이에요.
민지는 테이프 사진 두 장에 표시했어요. 한 장의 갈고리와 다른 장의 고리를 선으로 이었어요. 두 부분의 관계를 설명해야 붙는 까닭을 알 수 있어요.''',
'''민지는 테이프를 ‘작은 갈고리만 있는 물건’이라고 소개했다가 고리 면도 넣었어요. 한쪽만 설명하면 무엇에 걸리는지 빠지기 때문이에요. 비교 자료를 모을 때에는 닮은 모양뿐 아니라 함께 작용하는 부분도 찾아요.''',
'''친구는 자연에서 아이디어를 얻었으니 테이프도 식물로만 만들었다고 말했어요. 하지만 모양을 본뜬 것과 재료가 같은 것은 달라요. 어떤 점을 닮게 만들었는지 따져야 해요. 겉모습, 쓰임, 재료를 서로 다른 기준으로 나누면 잘못된 결론을 줄일 수 있어요.''',
[Q('갈고리는 다른 면의 무엇에 걸리나요?','작은 고리에 걸려요.',1,'갈고리가 고리에 걸려'),Q('갈고리와 고리를 함께 설명해야 하는 까닭은 무엇인가요?','서로 걸리는 관계가 붙는 까닭이기 때문이에요.',[1,3],'두 부분의 관계'),Q('식물의 어떤 특징이 도구의 생각과 연결되었나요?','다른 곳에 걸리는 모양이에요.',2,'걸리는 모양을 살핀'),Q('‘열매에서 생각을 얻었으니 테이프도 열매로 만들었다’고 해도 되나요?','모양을 본뜨는 것과 재료가 같은 것은 다른 말이에요.',[1,2],'식물의 색을 그대로 따라 한 것이 아니라')],
('갈매기의 날개 모양을 살펴 종이비행기를 만들었어요.','알맞은 설명은 무엇인가요?',['모양을 참고해도 재료까지 같지는 않아요.','새를 참고했으니 종이가 깃털로 바뀌었어요.','재료가 다르면 모양을 참고할 수 없어요.'],[2],'닮은 측면과 다른 측면을 구별해요.',['참고한 특징을 한정했어요.','모양에서 재료로 넘어갔어요.','서로 다른 기준을 섞었어요.']),[('갈고리','끝이 굽어 다른 것에 걸리는 모양'),('본뜨다','모양이나 방법을 참고해 만들다')],'발명 영감 식물의 불명확한 번역을 피하고 갈고리-고리 작용과 비교 측면을 명확화.', ['https://www.loc.gov/everyday-mysteries/categories/technology/item/who-came-up-with-the-idea-for-velcro/'])

add('G2-EXP-W3','음식이 지나는 길과 하는 일',
'''음식은 입에서 씹히고 침과 섞인 뒤 식도를 지나 위로 가요. 위에서는 음식이 소화액과 섞이고 더 잘게 나뉘어요. 음식이 물처럼 단순히 녹아 없어지는 것은 아니에요.
다음에는 작은창자를 지나며 소화된 영양분의 많은 부분이 몸으로 흡수돼요. 그 뒤 큰창자를 지나면서 물이 더 흡수되고 남은 찌꺼기가 몸 밖으로 나와요. 이는 길과 중요한 일을 간단히 설명한 글이에요.
민지는 입, 식도, 위, 작은창자, 큰창자를 화살표로 이었어요. 기관의 이름을 모두 적어도 순서를 바꾸면 음식이 지나는 길을 잘못 설명하게 돼요.''',
'''친구는 몸에 필요한 영양분과 남은 찌꺼기를 같은 것이라고 생각했어요. 민지는 ‘흡수된다’와 ‘몸 밖으로 나온다’에 다른 표시를 했어요. 어느 것이 어디로 이동하는지 나누어 읽으면 두 과정을 구별하기 쉬워요.''',
'''그림에는 기관의 실제 크기와 거리를 그대로 그리지 않을 수 있어요. 길의 차례를 보여 주기 위해 펼쳐 놓기도 해요. 민지는 그림에서 더 가까이 그려진 곳으로 화살표를 마음대로 바꾸지 않았어요. 모형 그림이 무엇을 설명하려는지 확인하고 글의 차례와 맞추었어요.''',
[Q('식도를 지난 음식이 가는 곳은 어디인가요?','위예요.',1,'식도를 지나 위로'),Q('작은창자의 영양분과 남은 찌꺼기는 어디로 가나요?','영양분은 몸으로 흡수되고 남은 찌꺼기는 뒤의 길을 거쳐 밖으로 나와요.',2,'몸으로 흡수돼요.'),Q('위 다음을 큰창자로 바로 연결한 그림에는 무엇이 빠졌나요?','작은창자가 빠졌어요.',[1,2],'다음에는 작은창자'),Q('기관 이름이 모두 있으면 길의 설명이 정확한가요?','음식이 지나는 순서도 맞아야 해요.',3,'순서를 바꾸면')],
('물이 정수 장치의 가 통, 나 거름망, 다 통을 차례로 지나간다고 해요.','가 통에서 다 통으로 바로 그은 화살표의 문제는 무엇인가요?',['나 거름망을 거치는 과정이 빠졌어요.','이름 세 개가 있으니 문제없어요.','가까운 곳으로 연결하면 언제나 맞아요.'],[3],'이름의 존재와 과정의 연결을 따로 확인해요.',['중간 단계를 확인했어요.','순서를 확인하지 않았어요.','그림 거리로 과정 순서를 정했어요.']),[('흡수','다른 곳으로 들어가 받아들여짐'),('기관','몸에서 정해진 일을 하는 부분')],'위에서 음식이 녹는다는 부정확한 비유를 고치고 경로·기능 정보 구별.')

add('G2-EXP-W4','민들레 씨는 어디까지 갈까요?',
'''민들레에는 작은 씨가 들어 있는 열매에 가벼운 털이 달려 있어요. 이 털은 바람에 실려 이동하는 데 도움이 돼요. 설명할 때에는 낙하산에 빗대기도 해요. 씨가 스스로 날개를 움직여 날아가는 것은 아니에요.
민지는 바람이 불자 하얀 털이 달린 것들이 흩어지는 모습을 보았어요. 가까이 내려앉은 것도 있고 더 멀리 간 것도 있었어요. 어디에 닿는지는 바람과 주변 조건에 따라 달라질 수 있어요.
땅에 닿았다고 모든 씨가 꼭 싹을 틔우는 것은 아니에요. 싹이 트기 알맞은 조건도 필요해요. 이동하는 일과 새로 자라는 일은 나누어 생각해야 해요.''',
'''민지는 ‘둥실둥실 움직였다’라는 말을 넣었어요. 흉내말은 본 모습을 생생하게 전할 수 있어요. 하지만 실제로 보지 않은 먼 곳까지 갔다고 꾸며 쓰면 관찰 글과 맞지 않아요. 생생한 표현과 사실을 함께 지켜요.''',
'''친구는 털이 달렸으니 모든 씨가 같은 거리만큼 날아간다고 말했어요. 민지는 본 것 중 가까운 곳과 먼 곳이 있었다고 알려 주었어요. 이동에 도움이 되는 특징이 있다고 결과까지 늘 같아지는 것은 아니에요. ‘도움이 된다’와 ‘반드시 그렇게 된다’를 구별해서 읽어요.''',
[Q('털은 어떤 일에 도움이 되나요?','바람에 실려 이동하는 데 도움이 돼요.',1,'바람에 실려 이동'),Q('가까이 간 것과 멀리 간 것이 생길 수 있는 까닭은 무엇인가요?','바람과 주변 조건이 다를 수 있기 때문이에요.',2,'바람과 주변 조건'),Q('땅에 닿은 씨가 자랐는지 알려면 무엇을 더 확인해야 하나요?','싹이 트기 알맞은 조건과 실제 자라는 모습을 확인해야 해요.',3,'알맞은 조건도 필요해요.'),Q('‘땅에 닿으면 다음 봄에 모두 싹이 난다’고 해도 되나요?','모든 씨가 반드시 싹트는 것은 아니므로 그렇게 단정하면 안 돼요.',3,'모든 씨가 꼭')],
('같은 종이비행기 두 개를 서로 다른 바람 속에서 날렸어요.','결과를 생각한 말로 알맞은 것은 무엇인가요?',['모양이 같아도 날아간 거리는 다를 수 있어요.','모양이 같으니 거리도 꼭 같아요.','바람은 어느 비행에도 관계없어요.'],[1,2],'공통 특징과 달라진 조건을 함께 봐요.',['추가 조건을 고려했어요.','하나의 조건만으로 결과를 정했어요.','본문과 연결되는 조건을 지웠어요.']),[('빗대다','비슷한 다른 것에 견주어 설명하다'),('조건','결과와 관련 있는 상황')],'열매·씨 표현을 바로잡고 낙하 뒤 필연 발아 단정 삭제.')

add('G2-EXP-W5','상징을 정확하게 소개해요',
'''태극기는 우리나라의 국기예요. 흰 바탕 가운데 태극 무늬가 있고 네 모서리에 검은 괘가 있어요. 민지는 소개 글을 쓰며 바탕, 가운데, 모서리를 나누어 관찰했어요. 부분마다 어떤 모양과 색인지 확인한 거예요.
무궁화는 우리나라를 상징하는 꽃이에요. 꽃이 피는 때에 새 꽃이 이어서 피지만, 한 송이가 영원히 시들지 않는 것은 아니에요. 여러 송이의 피는 모습과 한 송이의 생김을 구별해야 해요.
민지는 ‘무궁화 한 송이는 지지 않는다’라는 문장을 고쳤어요. 자랑하는 마음을 나타내더라도 사실과 다른 설명을 그대로 남기지 않았어요.''',
'''민지는 친구에게 글을 읽어 달라고 했어요. 친구는 태극 무늬와 모서리의 괘를 서로 바꾸어 쓴 부분을 찾았어요. 맞춤법만 맞아도 내용의 위치와 색이 틀릴 수 있어요. 글과 확인 자료를 나란히 놓고 고쳐요.''',
'''다른 친구는 그림이 작아서 모서리의 무늬가 잘 보이지 않는다고 했어요. 민지는 기억만으로 채우기보다 더 선명한 자료를 찾았어요. 소개하는 사람이 확신한다고 근거가 생기는 것은 아니에요. 확인하기 어려운 부분을 먼저 표시하면 무엇을 다시 찾아야 할지 알 수 있어요.''',
[Q('태극기의 네 모서리에 있는 것은 무엇인가요?','검은 괘예요.',1,'네 모서리에 검은 괘'),Q('새 꽃이 이어서 피는 것과 한 송이가 영원히 피는 것은 어떻게 다른가요?','꽃이 바뀌며 이어 피는 것이지 같은 한 송이가 계속 남는 것은 아니에요.',2,'한 송이가 영원히 시들지 않는 것은 아니에요.'),Q('작은 그림에서 무늬가 잘 보이지 않으면 어떻게 확인해야 하나요?','잘 보이는 자료를 더 찾아 확인해야 해요.',1,'모양과 색인지 확인'),Q('‘좋은 뜻을 담은 글이니 사실이 틀려도 괜찮다’고 해도 되나요?','마음과 사실은 구별해서 틀린 설명을 고쳐야 해요.',3,'사실과 다른 설명')],
('정원의 꽃이 여러 날 이어 피었어요. 날마다 새 꽃이 피고 먼저 핀 꽃은 시들었어요.','정확한 설명은 무엇인가요?',['새 꽃이 이어 피어 정원에 꽃이 계속 보였어요.','처음 핀 한 송이가 영원히 남았어요.','꽃이 늘 보였으니 시든 꽃은 하나도 없어요.'],[2],'전체의 지속과 개별 대상의 변화를 구별해요.',['관찰한 과정과 맞아요.','서로 다른 꽃을 같은 꽃으로 여겼어요.','전체 모습으로 개별 변화를 부정했어요.']),[('상징','어떤 나라나 뜻을 나타내는 것'),('괘','태극기 모서리에 있는 선으로 된 무늬')],'무궁화 한 송이가 영원히 지지 않는다는 오류와 형식 위주 퇴고를 수정.')

